"use strict";(self.webpackChunktmrw_help=self.webpackChunktmrw_help||[]).push([["4444"],{83789(e){e.exports=JSON.parse('{"version":{"pluginId":"hr","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"autogenerated":[{"type":"link","href":"/hr/","label":"HR \u2013 Dynamics 365 Guide","docId":"index","unlisted":false},{"type":"category","label":"Navigating D365 HR","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Navigating/sign-in-d365","label":"Sign in to Dynamics 365 HR","docId":"Navigating/sign-in-d365","unlisted":false},{"type":"link","href":"/hr/Navigating/navigate-d365","label":"Navigate Dynamics 365 HR","docId":"Navigating/navigate-d365","unlisted":false}]},{"type":"category","label":"Questionnaires","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Questionnaires/set-up-questionnaire-schedule","label":"Set up a questionnaire schedule","docId":"Questionnaires/set-up-questionnaire-schedule","unlisted":false},{"type":"link","href":"/hr/Questionnaires/view-intentions-inquiry","label":"View the intentions inquiry","docId":"Questionnaires/view-intentions-inquiry","unlisted":false},{"type":"link","href":"/hr/Questionnaires/update-retention-status","label":"Update an employee\'s retention status","docId":"Questionnaires/update-retention-status","unlisted":false},{"type":"link","href":"/hr/Questionnaires/run-offboarding-questionnaire-batch","label":"Run the offboarding questionnaire batch","docId":"Questionnaires/run-offboarding-questionnaire-batch","unlisted":false}]},{"type":"category","label":"Onboarding","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Onboarding/configure-onboarding-checklist","label":"Configure an onboarding checklist","docId":"Onboarding/configure-onboarding-checklist","unlisted":false},{"type":"link","href":"/hr/Onboarding/set-checklist-dependencies","label":"Set checklist task dependencies","docId":"Onboarding/set-checklist-dependencies","unlisted":false},{"type":"link","href":"/hr/Onboarding/configure-school-specific-checklist","label":"Configure a school-specific checklist task","docId":"Onboarding/configure-school-specific-checklist","unlisted":false},{"type":"link","href":"/hr/Onboarding/configure-preonboarding-checklist","label":"Configure a pre-onboarding checklist","docId":"Onboarding/configure-preonboarding-checklist","unlisted":false},{"type":"link","href":"/hr/Onboarding/configure-task-user-groups","label":"Configure task user groups","docId":"Onboarding/configure-task-user-groups","unlisted":false},{"type":"link","href":"/hr/Onboarding/set-onboarding-parameters","label":"Set onboarding parameters","docId":"Onboarding/set-onboarding-parameters","unlisted":false},{"type":"link","href":"/hr/Onboarding/configure-personal-action-types","label":"Configure personal action types for onboarding","docId":"Onboarding/configure-personal-action-types","unlisted":false},{"type":"link","href":"/hr/Onboarding/assign-preonboarding-checklist-on-hire","label":"Assign a pre-onboarding checklist on hire","docId":"Onboarding/assign-preonboarding-checklist-on-hire","unlisted":false}]},{"type":"category","label":"Visa and work authorisation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Visa-Work-Authorisation/visa-status-setup","label":"Manage visa status setup","docId":"Visa-Work-Authorisation/visa-status-setup","unlisted":false},{"type":"link","href":"/hr/Visa-Work-Authorisation/visa-type-setup","label":"Manage visa type setup","docId":"Visa-Work-Authorisation/visa-type-setup","unlisted":false},{"type":"link","href":"/hr/Visa-Work-Authorisation/manage-mol-professions","label":"Manage MOL professions","docId":"Visa-Work-Authorisation/manage-mol-professions","unlisted":false},{"type":"link","href":"/hr/Visa-Work-Authorisation/manage-moe-professions","label":"Manage MOE professions","docId":"Visa-Work-Authorisation/manage-moe-professions","unlisted":false},{"type":"link","href":"/hr/Visa-Work-Authorisation/manage-contract-types","label":"Manage contract types","docId":"Visa-Work-Authorisation/manage-contract-types","unlisted":false},{"type":"link","href":"/hr/Visa-Work-Authorisation/view-visa-information","label":"View visa information for an employee","docId":"Visa-Work-Authorisation/view-visa-information","unlisted":false},{"type":"link","href":"/hr/Visa-Work-Authorisation/view-expiring-records","label":"View expiring records","docId":"Visa-Work-Authorisation/view-expiring-records","unlisted":false},{"type":"link","href":"/hr/Visa-Work-Authorisation/review-pending-worker-visa","label":"Review pending worker visa information","docId":"Visa-Work-Authorisation/review-pending-worker-visa","unlisted":false}]},{"type":"category","label":"HR Requests","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Requests/configure-request-types","label":"Configure HR request types","docId":"Requests/configure-request-types","unlisted":false},{"type":"link","href":"/hr/Requests/process-an-hr-request","label":"Process an HR request","docId":"Requests/process-an-hr-request","unlisted":false}]},{"type":"category","label":"Probation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Probation/configure-probation-settings","label":"Configure probation settings","docId":"Probation/configure-probation-settings","unlisted":false},{"type":"link","href":"/hr/Probation/probation-fields-on-employee-record","label":"Probation fields on an employee record","docId":"Probation/probation-fields-on-employee-record","unlisted":false},{"type":"link","href":"/hr/Probation/generate-probation-reviews","label":"Generate probation reviews","docId":"Probation/generate-probation-reviews","unlisted":false},{"type":"link","href":"/hr/Probation/monitor-probation-reviews","label":"Monitor probation reviews","docId":"Probation/monitor-probation-reviews","unlisted":false}]},{"type":"category","label":"Identification","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Identification/configure-mandatory-attachments","label":"Configure mandatory attachments and fields for identification","docId":"Identification/configure-mandatory-attachments","unlisted":false}]},{"type":"category","label":"Benefits","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Benefits/configure-reward-types","label":"Configure reward types on the component master","docId":"Benefits/configure-reward-types","unlisted":false}]},{"type":"category","label":"Offboarding","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/hr/Offboarding/configure-offboarding-checklist","label":"Configure an Offboarding Checklist","docId":"Offboarding/configure-offboarding-checklist","unlisted":false},{"type":"link","href":"/hr/Offboarding/assign-offboarding-checklist-offboarding-employees","label":"Assign the Offboarding Checklist to Offboarding Employees","docId":"Offboarding/assign-offboarding-checklist-offboarding-employees","unlisted":false}]}]},"docs":{"Benefits/configure-reward-types":{"id":"Benefits/configure-reward-types","title":"Configure reward types on the component master","description":"The Reward Type field on the component master classifies compensation and benefit components so they appear in the correct category on the employee rewards statement in ESS. Components without a reward type are excluded from the statement. This is a one-time configuration step for each applicable component.","sidebar":"autogenerated"},"Identification/configure-mandatory-attachments":{"id":"Identification/configure-mandatory-attachments","title":"Configure mandatory attachments and fields for identification","description":"Each identification document type can have its own set of required fields and attachment rules. When an attachment is made mandatory, the Submit button in ESS is disabled until the employee uploads a file \u2014 preventing incomplete submissions.","sidebar":"autogenerated"},"index":{"id":"index","title":"HR \u2013 Dynamics 365 Guide","description":"This guide is for HR professionals, HR business partners, PRO teams, and system administrators using Dynamics 365 Human Resources to manage employee data, configure processes, and monitor compliance across GEMS schools.","sidebar":"autogenerated"},"Navigating/navigate-d365":{"id":"Navigating/navigate-d365","title":"Navigate Dynamics 365 HR","description":"1. Open the navigation pane","sidebar":"autogenerated"},"Navigating/sign-in-d365":{"id":"Navigating/sign-in-d365","title":"Sign in to Dynamics 365 HR","description":"D365 HR uses your GEMS Microsoft 365 account \u2014 the same login you use for email.","sidebar":"autogenerated"},"Offboarding/assign-offboarding-checklist-offboarding-employees":{"id":"Offboarding/assign-offboarding-checklist-offboarding-employees","title":"Assign the Offboarding Checklist to Offboarding Employees","description":"Send out the offboarding checklist to employees who are leaving the company.","sidebar":"autogenerated"},"Offboarding/configure-offboarding-checklist":{"id":"Offboarding/configure-offboarding-checklist","title":"Configure an Offboarding Checklist","description":"Prepare the offboarding checklist for staff members who are leaving the company. Assign the primary user who will follow up on the offboarding process and identify who the task can be delegated to.","sidebar":"autogenerated"},"Onboarding/assign-preonboarding-checklist-on-hire":{"id":"Onboarding/assign-preonboarding-checklist-on-hire","title":"Assign a pre-onboarding checklist on hire","description":"When processing a hire worker action in D365, you can assign a pre-onboarding checklist directly from the worker action form. This releases tasks to the designated HR teams or individuals immediately, so pre-onboarding activities can begin before the new employee\'s official start date.","sidebar":"autogenerated"},"Onboarding/configure-onboarding-checklist":{"id":"Onboarding/configure-onboarding-checklist","title":"Configure an onboarding checklist","description":"Onboarding checklists define the tasks assigned to a new employee and their supporting teams upon joining the organisation. Tasks can be assigned to a specific person, a user group, or left for manual assignment at the time of hire.","sidebar":"autogenerated"},"Onboarding/configure-personal-action-types":{"id":"Onboarding/configure-personal-action-types","title":"Configure personal action types for onboarding","description":"The Personal action types form controls which hire action types trigger the automatic application of an onboarding checklist when a worker action is completed. This flag must be enabled on each relevant action type.","sidebar":"autogenerated"},"Onboarding/configure-preonboarding-checklist":{"id":"Onboarding/configure-preonboarding-checklist","title":"Configure a pre-onboarding checklist","description":"Pre-onboarding checklists define tasks that must be completed by HR and support teams before a new employee\'s start date \u2014 for example, collecting credentials or sending welcome documents. These checklists are assigned when the hire worker action is processed, and tasks are visible in both the D365 task management workspace and ESS.","sidebar":"autogenerated"},"Onboarding/configure-school-specific-checklist":{"id":"Onboarding/configure-school-specific-checklist","title":"Configure a school-specific checklist task","description":"Tasks within an onboarding checklist can be scoped to specific legal entities (schools), so only relevant tasks appear for employees at each school. Tasks with no company restriction apply to all schools.","sidebar":"autogenerated"},"Onboarding/configure-task-user-groups":{"id":"Onboarding/configure-task-user-groups","title":"Configure task user groups","description":"User groups allow multiple employees to be assigned to a checklist task together. When any one member of the group completes the task, it is automatically marked complete and removed from the task lists of all other group members. The Resolved By column in the task management workspace records which group member completed the task.","sidebar":"autogenerated"},"Onboarding/set-checklist-dependencies":{"id":"Onboarding/set-checklist-dependencies","title":"Set checklist task dependencies","description":"Dependencies prevent a task from being completed until a prerequisite task is finished first \u2014 for example, setting up a laptop depends on the Active Directory account being created.","sidebar":"autogenerated"},"Onboarding/set-onboarding-parameters":{"id":"Onboarding/set-onboarding-parameters","title":"Set onboarding parameters","description":"The Human Resources parameters form controls which onboarding checklist is applied automatically when a hire worker action is completed, and how many days the new employee has to complete their onboarding tasks.","sidebar":"autogenerated"},"Probation/configure-probation-settings":{"id":"Probation/configure-probation-settings","title":"Configure probation settings","description":"Probation review settings are configured by staff level and category, controlling when Stage 1 and Stage 2 reviews are triggered for different employee types.","sidebar":"autogenerated"},"Probation/generate-probation-reviews":{"id":"Probation/generate-probation-reviews","title":"Generate probation reviews","description":"The Generate Probation Reviews batch process scans employee records for upcoming probation dates and creates the review records, routing them into the approval workflow for the assigned manager.","sidebar":"autogenerated"},"Probation/monitor-probation-reviews":{"id":"Probation/monitor-probation-reviews","title":"Monitor probation reviews","description":"HR can view all probation reviews \u2014 in progress or completed \u2014 from a central form in D365, including workflow status, manager ratings, and employee feedback.","sidebar":"autogenerated"},"Probation/probation-fields-on-employee-record":{"id":"Probation/probation-fields-on-employee-record","title":"Probation fields on an employee record","description":"Probation fields are automatically populated in an employee\'s record when the employee is created in the system. HR can view and update these fields at any point during the process.","sidebar":"autogenerated"},"Questionnaires/run-offboarding-questionnaire-batch":{"id":"Questionnaires/run-offboarding-questionnaire-batch","title":"Run the offboarding questionnaire batch","description":"The offboarding exit survey is generated automatically via a batch job that detects employees assigned to an offboarding checklist. Run this batch to assign the exit questionnaire to departing employees.","sidebar":"autogenerated"},"Questionnaires/set-up-questionnaire-schedule":{"id":"Questionnaires/set-up-questionnaire-schedule","title":"Set up a questionnaire schedule","description":"Questionnaire schedules target a questionnaire to specific employees across one or more legal entities. Schedules are typically created in the GCO entity and can be released to individual schools or across all companies.","sidebar":"autogenerated"},"Questionnaires/update-retention-status":{"id":"Questionnaires/update-retention-status","title":"Update an employee\'s retention status","description":"As your retention conversation with an employee progresses, update their status in the Intentions Inquiry to keep the record up to date.","sidebar":"autogenerated"},"Questionnaires/view-intentions-inquiry":{"id":"Questionnaires/view-intentions-inquiry","title":"View the intentions inquiry","description":"The Employee Intention Survey Result form displays all employees who answered \\"Yes\\" to the intention-to-leave question in the Intention Questionnaire. Responses are captured live as employees submit the survey through ESS.","sidebar":"autogenerated"},"Requests/configure-request-types":{"id":"Requests/configure-request-types","title":"Configure HR request types","description":"Request types define what employees can request through the ESS portal, which fields appear on the submission form, what is required before submitting, and which approval workflow the request follows.","sidebar":"autogenerated"},"Requests/process-an-hr-request":{"id":"Requests/process-an-hr-request","title":"Process an HR request","description":"When an employee submits a request through ESS, it is routed to the HR team via the configured workflow. HR reviews the submission, provides feedback, and marks it complete.","sidebar":"autogenerated"},"Visa-Work-Authorisation/manage-contract-types":{"id":"Visa-Work-Authorisation/manage-contract-types","title":"Manage contract types","description":"Contract types define the employment contract categories used when recording visa and employment information (for example: Full Time, Limited, Part Time). These values are configured once during initial setup and rarely change.","sidebar":"autogenerated"},"Visa-Work-Authorisation/manage-moe-professions":{"id":"Visa-Work-Authorisation/manage-moe-professions","title":"Manage MOE professions","description":"MOE (Ministry of Education) professions define the occupational classifications relevant to the education sector, used to categorise employee roles in line with Ministry requirements.","sidebar":"autogenerated"},"Visa-Work-Authorisation/manage-mol-professions":{"id":"Visa-Work-Authorisation/manage-mol-professions","title":"Manage MOL professions","description":"MOL (Ministry of Labour) professions define the occupational classifications required for labour regulatory compliance. All standard MOL professions are pre-loaded into the system.","sidebar":"autogenerated"},"Visa-Work-Authorisation/review-pending-worker-visa":{"id":"Visa-Work-Authorisation/review-pending-worker-visa","title":"Review pending worker visa information","description":"When an applicant is hired through the recruitment process, any identification records added to the applicant record (such as passport or visa details) automatically carry over to the Pending Worker Visa Information form. The HR or PRO team uses this form to confirm documents are present and to complete additional visa-related fields before finalising the hire. When the worker\'s action is completed, all information is published to the employee\'s record.","sidebar":"autogenerated"},"Visa-Work-Authorisation/view-expiring-records":{"id":"Visa-Work-Authorisation/view-expiring-records","title":"View expiring records","description":"The Expiring Records workspace gives HR and PRO teams a centralised view of all employee documents approaching or past their expiry dates.","sidebar":"autogenerated"},"Visa-Work-Authorisation/view-visa-information":{"id":"Visa-Work-Authorisation/view-visa-information","title":"View visa information for an employee","description":"The visa information form captures all fields required for visa processing and regulatory compliance for an individual employee. This is typically completed by the HR or PRO team.","sidebar":"autogenerated"},"Visa-Work-Authorisation/visa-status-setup":{"id":"Visa-Work-Authorisation/visa-status-setup","title":"Manage visa status setup","description":"Visa statuses define the lifecycle stages used to track the progress of visa and labour card applications. These values are set during initial configuration and apply to all employee visa records.","sidebar":"autogenerated"},"Visa-Work-Authorisation/visa-type-setup":{"id":"Visa-Work-Authorisation/visa-type-setup","title":"Manage visa type setup","description":"Visa types define the categories of visas available when recording employee visa information. These values were pre-loaded from the organisation\'s prior system during migration.","sidebar":"autogenerated"}}}}')}}]);